//! The NLCS++ Netbeheer V12.1 information model, generated by
//! `tools/import_nlcspp.py` from the official sources (see `assets/NOTICE`).

use std::collections::{BTreeMap, HashSet};
use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Debug, Deserialize)]
pub struct Field {
    pub name: String,
    /// `string`, `integer`, `decimal`, `date`, `dateTime`, `ID`, `IDREF`,
    /// `list` (a code list), `geometry`, …
    #[serde(rename = "type")]
    pub kind: String,
    pub required: bool,
    #[serde(default)]
    pub max_length: Option<usize>,
    /// The code list of a `list` field.
    #[serde(default)]
    pub list: Option<String>,
    /// An inline enumeration.
    #[serde(default, rename = "enum")]
    pub values: Option<Vec<String>>,
}

#[derive(Debug, Deserialize)]
pub struct ObjectDef {
    /// `point`, `curve`, `surface`, … (GML property type).
    pub geometrie: Option<String>,
    pub velden: Vec<Field>,
}

#[derive(Debug, Deserialize)]
pub struct Operator {
    pub xsd: String,
    pub namespace: Option<String>,
    pub keuzelijsten: BTreeMap<String, Vec<String>>,
}

#[derive(Debug, Deserialize)]
pub struct Model {
    pub versie: String,
    pub root: String,
    pub namespace: String,
    pub project: Vec<Field>,
    pub objecten: BTreeMap<String, ObjectDef>,
    /// The general code lists (Status, Bedrijfstoestand, Tekeningtype, …).
    pub keuzelijsten: BTreeMap<String, Vec<String>>,
    pub netbeheerders: BTreeMap<String, Operator>,
    /// Per object: attribute → position of its value in the layer name.
    pub laagnaam_posities: BTreeMap<String, BTreeMap<String, usize>>,
    /// Per object: attribute → position of its value in the symbol name.
    pub symboolnaam_posities: BTreeMap<String, BTreeMap<String, usize>>,
}

pub fn model() -> &'static Model {
    static M: OnceLock<Model> = OnceLock::new();
    M.get_or_init(|| serde_json::from_str(include_str!("../assets/model-v12.1.json")).expect("NLCS++ model"))
}

/// The operator as the model names it: `Liander` and `NRG` count as Alliander.
pub fn operator(name: &str) -> Option<&'static str> {
    let n = name.trim().to_ascii_lowercase();
    let key = if n.contains("alliander") || n.contains("liander") || n.contains("nrg") {
        "Alliander"
    } else if n.contains("enexis") {
        "Enexis"
    } else if n.contains("stedin") {
        "Stedin"
    } else {
        return None;
    };
    model().netbeheerders.contains_key(key).then_some(key)
}

/// The operator's value in the code list `Netbeheerder` (Alliander delivers as Liander).
pub fn netbeheerder_value(operator: &str) -> &'static str {
    match operator {
        "Alliander" => "Liander",
        "Enexis" => "Enexis",
        "Stedin" => "Stedin",
        _ => "Enexis",
    }
}

impl Model {
    /// The values of a code list: the operator's own when it fills it, else the general one.
    pub fn list(&self, operator: Option<&str>, name: &str) -> Option<&[String]> {
        operator
            .and_then(|o| self.netbeheerders.get(o))
            .and_then(|o| o.keuzelijsten.get(name))
            .filter(|v| !v.is_empty())
            .or_else(|| self.keuzelijsten.get(name).filter(|v| !v.is_empty()))
            .map(Vec::as_slice)
    }

    pub fn object(&self, kind: &str) -> Option<&ObjectDef> {
        self.objecten.get(kind)
    }
}

/// The layer names of an operator's DWG template (V11), without the status
/// letter's variants. Stedin has no published template: Enexis's stands in.
pub fn template_layers(operator: Option<&str>) -> &'static HashSet<String> {
    static A: OnceLock<HashSet<String>> = OnceLock::new();
    static E: OnceLock<HashSet<String>> = OnceLock::new();
    let load = |s: &'static str| s.lines().map(str::to_string).collect::<HashSet<String>>();
    match operator {
        Some("Alliander") => A.get_or_init(|| load(include_str!("../assets/lagen-alliander.txt"))),
        _ => E.get_or_init(|| load(include_str!("../assets/lagen-enexis.txt"))),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_model_loads() {
        let m = model();
        assert_eq!(m.objecten.len(), 56);
        assert!(m.objecten["LSkabel"].velden.iter().any(|f| f.name == "Status" && f.required));
        assert_eq!(m.objecten["LSkabel"].geometrie.as_deref(), Some("curve"));
        assert_eq!(m.list(None, "Status").unwrap(), ["BESTAAND", "NIEUW", "REVISIE", "VERWIJDERD"]);
        assert!(m.list(Some("Enexis"), "UitvoeringLSKabel").unwrap().iter().any(|v| v == "4x150Al"));
        assert_ne!(m.list(Some("Alliander"), "UitvoeringLSKabel"), m.list(Some("Enexis"), "UitvoeringLSKabel"), "operator lists differ");
        assert_eq!(operator("Liander N.V."), Some("Alliander"));
        assert!(template_layers(Some("Enexis")).len() > 5000);
    }
}
